package com.careerpilot.modules.careerplan.controller;
import com.careerpilot.modules.careerplan.dto.CareerPlanDtos.*;import com.careerpilot.modules.careerplan.service.CareerPlanService;import com.careerpilot.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController@RequestMapping("/api/v1/career-plans")public class CareerPlanController{private final CareerPlanService service;public CareerPlanController(CareerPlanService service){this.service=service;}@PostMapping@ResponseStatus(HttpStatus.CREATED)public PlanResponse create(@Valid@RequestBody CreatePlanRequest request){return service.create(CurrentUser.require(),request);}@GetMapping("/current")public ResponseEntity<PlanResponse>current(){return ResponseEntity.ofNullable(service.current(CurrentUser.require()));}@PatchMapping("/items/{itemId}")public PlanResponse update(@PathVariable UUID itemId,@Valid@RequestBody UpdateStatusRequest request){return service.updateStatus(CurrentUser.require(),itemId,request);}}
